// Demo: Financial Scenario Analyzer - public implementations survey
(function(){'use strict';
var DATA={"label": "Financial Scenario Analyzer - public implementations survey", "items": [{"name": "Double-entry bookkeeping", "qty": 4, "unit": 146.34}, {"name": "GAAP", "qty": 8, "unit": 250.45}, {"name": "NPV and IRR", "qty": 6, "unit": 160.6}, {"name": "Amortization schedules", "qty": 7, "unit": 285.14}], "contingency": 15};

var sub=0;
console.log('Estimate: '+DATA.label);
DATA.items.forEach(function(it){var c=it.qty*it.unit;
  console.log('  '+it.name+': '+it.qty+' x $'+it.unit.toFixed(2)+' = $'+c.toFixed(2));sub+=c;});
var cont=sub*DATA.contingency/100, total=sub+cont;
console.log('Subtotal: $'+sub.toFixed(2));
console.log('Contingency ('+DATA.contingency+'%): $'+cont.toFixed(2));
console.log('TOTAL: $'+total.toFixed(2));
})();

