// Demo: Builder drill - compare two approaches to Financial Scenario Analyzer on the
(function(){'use strict';
var DATA={"label": "Builder drill - compare two approaches to Financial Scenario", "entries": [{"account": "cash", "debit": 295, "credit": 0}, {"account": "equipment", "debit": 405, "credit": 0}, {"account": "revenue", "debit": 0, "credit": 295}, {"account": "notes-payable", "debit": 0, "credit": 405}]};

var bal={};
console.log('Posting '+DATA.entries.length+' journal lines ('+DATA.label+'):');
DATA.entries.forEach(function(e){
  bal[e.account]=bal[e.account]||0;
  bal[e.account]+=e.debit-e.credit;
  console.log('  '+e.account+': debit '+e.debit+' credit '+e.credit);});
var debits=0,credits=0;
DATA.entries.forEach(function(e){debits+=e.debit;credits+=e.credit;});
console.log('Trial balance:');
Object.keys(bal).sort().forEach(function(a){console.log('  '+a+': '+bal[a].toFixed(2));});
console.log(debits===credits?'BALANCED - debits = credits = '+debits:'OUT OF BALANCE!');
})();

